<section id="system-settings" class="view">
    <h1 class="mb-6 text-balance text-3xl font-black">System Settings</h1>
    <div class="mb-6 rounded-2xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900 sm:p-6">
        <h2 class="text-lg font-bold">Workspace and academic defaults</h2>
        <p class="mt-1 text-sm text-slate-600 dark:text-slate-300">Manage the active academic period, rules, pagination, and workspace label.</p>
        <form id="systemSettingsForm" data-submit="submitSystemSettings" class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            <label class="text-sm font-semibold">Active school year<input name="activeSchoolYear" pattern="(\d{4}[-–]\d{4})?" placeholder="Auto (e.g. 2025-2026)" class="mt-1 block w-full rounded-xl border bg-slate-50 px-3 py-2 text-sm font-normal tabular-nums dark:border-slate-700 dark:bg-slate-800"></label>
            <label class="text-sm font-semibold">Active semester<select id="settingsActiveSemester" name="activeSemester" class="mt-1 block w-full rounded-xl border bg-slate-50 px-3 py-2 text-sm font-normal dark:border-slate-700 dark:bg-slate-800"><?php foreach (SCHOLAR_SEMESTERS as $semester): ?><option><?= htmlspecialchars($semester, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label>
            <label class="text-sm font-semibold">Rows per page<select name="pageSize" class="mt-1 block w-full rounded-xl border bg-slate-50 px-3 py-2 text-sm font-normal dark:border-slate-700 dark:bg-slate-800"><option value="10">10 rows</option><option value="15">15 rows</option><option value="25">25 rows</option><option value="50">50 rows</option></select></label>
            <label class="text-sm font-semibold">TES / TDP max residency<input name="maxResidencyYears" type="number" min="1" max="10" required class="mt-1 block w-full rounded-xl border bg-slate-50 px-3 py-2 text-sm font-normal tabular-nums dark:border-slate-700 dark:bg-slate-800"></label>
            <label class="text-sm font-semibold">Default in-house status<select name="inHouseDefaultStatus" class="mt-1 block w-full rounded-xl border bg-slate-50 px-3 py-2 text-sm font-normal dark:border-slate-700 dark:bg-slate-800"><option value="Approved">Approved</option><option value="Pending">Pending</option></select></label>
            <label class="text-sm font-semibold">Workspace subtitle<input name="workspaceSubtitle" required maxlength="120" class="mt-1 block w-full rounded-xl border bg-slate-50 px-3 py-2 text-sm font-normal dark:border-slate-700 dark:bg-slate-800"></label>
            <label class="flex items-center gap-2 text-sm font-semibold sm:col-span-2 lg:col-span-3"><input name="externalRequiresApproval" type="checkbox" class="accent-dyci-blue"><span>Require approval for external grants</span></label>
            <div class="flex flex-wrap gap-3 sm:col-span-2 lg:col-span-3"><button type="submit" class="rounded-xl bg-dyci-blue px-4 py-2.5 text-sm font-bold text-white">Save system settings</button><button type="button" data-click="resetSystemSettings" class="rounded-xl border px-4 py-2.5 text-sm font-bold">Reset defaults</button></div>
        </form>
    </div>
    <div class="grid gap-6 lg:grid-cols-2">
        <section class="rounded-2xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><h2 class="text-lg font-bold">College departments</h2><form id="departmentForm" data-submit="submitAcademicItem" class="mt-4 flex gap-2"><input type="hidden" name="kind" value="department"><input name="value" required maxlength="160" placeholder="e.g. College of Engineering" class="min-w-0 flex-1 rounded-xl border bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"><button class="rounded-xl bg-dyci-blue px-4 py-2 text-sm font-bold text-white">Add</button></form><div id="departmentList" class="mt-4 space-y-2"></div></section>
        <section class="rounded-2xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><h2 class="text-lg font-bold">Programs and courses</h2><form id="programForm" data-submit="submitAcademicItem" class="mt-4 grid gap-2 sm:grid-cols-[8rem_1fr_auto]"><input type="hidden" name="kind" value="program"><input name="code" required maxlength="32" placeholder="BSIT" class="rounded-xl border bg-slate-50 px-3 py-2 text-sm uppercase dark:border-slate-700 dark:bg-slate-800"><input name="value" required maxlength="160" placeholder="Information Technology" class="rounded-xl border bg-slate-50 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"><button class="rounded-xl bg-dyci-blue px-4 py-2 text-sm font-bold text-white">Add</button></form><div id="programList" class="mt-4 space-y-2"></div></section>
    </div>
</section>
